const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const time=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
async function api(path='',data){const r=await fetch('/api/song-phrasing'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'处理未完成');return v;}
function select(label,id,entries){const wrap=el('label',label,'project-field'),control=el('select');control.id=id;for(const [value,text] of entries){const option=el('option',text);option.value=value;control.append(option);}wrap.append(control);return {wrap,control};}
